import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Comment","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/comment.md","filePath":"03-developer/models/comment.md"}`),a={name:`03-developer/models/comment.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="comment" tabindex="-1">Comment <a class="header-anchor" href="#comment" aria-label="Permalink to “Comment”">​</a></h1><h2 id="table-comments" tabindex="-1">Table: <code>comments</code> <a class="header-anchor" href="#table-comments" aria-label="Permalink to “Table: comments”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Comment</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique comment identifier</td></tr><tr><td><code>body</code></td><td>TEXT</td><td>No</td><td>Comment text</td></tr><tr><td><code>name</code></td><td>VARCHAR(100)</td><td>Yes</td><td>Guest author&#39;s name</td></tr><tr><td><code>email</code></td><td>VARCHAR(100)</td><td>Yes</td><td>Guest author&#39;s email address</td></tr><tr><td><code>ip</code></td><td>VARCHAR(45)</td><td>No</td><td>IP address of the comment submitter</td></tr><tr><td><code>status</code></td><td>TINYINT</td><td>No</td><td>Comment review status</td></tr><tr><td><code>parent_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>Parent comment identifier for replies</td></tr><tr><td><code>commentable_type</code></td><td>VARCHAR(255)</td><td>No</td><td>Type of the content model the comment belongs to</td></tr><tr><td><code>commentable_id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Identifier of the content the comment belongs to</td></tr><tr><td><code>commentator_type</code></td><td>VARCHAR(255)</td><td>Yes</td><td>Type of the model for the registered author</td></tr><tr><td><code>commentator_id</code></td><td>BIGINT UNSIGNED</td><td>Yes</td><td>Identifier of the registered author</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Comment creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last comment update</td></tr></tbody></table><h2 id="additional-field-details" tabindex="-1">Additional Field Details <a class="header-anchor" href="#additional-field-details" aria-label="Permalink to “Additional Field Details”">​</a></h2><ul><li><code>body</code>: The text of the submitted comment or reply.</li><li><code>status</code>: The comment review status: <ul><li><code>-1</code>: Rejected</li><li><code>0</code>: Pending</li><li><code>1</code>: Accepted</li></ul></li><li><code>parent_id</code>: The parent comment identifier for replies. A <code>NULL</code> value indicates that the comment has no specified parent.</li><li><code>commentable_type</code> and <code>commentable_id</code>: Specify a polymorphic relationship with the content the comment is about, such as a product or clip.</li><li><code>commentator_type</code> and <code>commentator_id</code>: Identify the registered author. The author can be a customer or a system administrator.</li><li><code>name</code> and <code>email</code>: Store the guest author&#39;s information, that is, the information of someone who submits a comment without a system account.</li><li>Guest author information and registered author information are alternative ways to identify the author and should not be used simultaneously.</li><li><code>ip</code>: Stores the IP address of the comment submitter.</li></ul><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="commentable" tabindex="-1"><code>commentable()</code> <a class="header-anchor" href="#commentable" aria-label="Permalink to “commentable()”">​</a></h3><p>Defines a polymorphic <code>morphTo</code> relationship and returns the content the comment belongs to.</p><h3 id="children" tabindex="-1"><code>children()</code> <a class="header-anchor" href="#children" aria-label="Permalink to “children()”">​</a></h3><p>Returns all comments whose <code>parent_id</code> matches this comment&#39;s identifier; that is, its direct replies.</p><h3 id="parent" tabindex="-1"><code>parent()</code> <a class="header-anchor" href="#parent" aria-label="Permalink to “parent()”">​</a></h3><p>Defines a <code>belongsTo</code> relationship with the <code>Comment</code> model and returns the parent comment through <code>parent_id</code>.</p><h3 id="approved-children" tabindex="-1"><code>approved_children()</code> <a class="header-anchor" href="#approved-children" aria-label="Permalink to “approved_children()”">​</a></h3><p>Retrieves related replies through a <code>hasMany</code> relationship with the condition <code>status = 1</code>; that is, it returns only approved replies.</p><p><strong>Note:</strong> In the current code, this relationship uses the <code>sub_comment_id</code> column, whereas the <code>children()</code> relationship is defined based on <code>parent_id</code>. If <code>sub_comment_id</code> does not exist in the table, this method needs to be corrected.</p><h3 id="commentator" tabindex="-1"><code>commentator()</code> <a class="header-anchor" href="#commentator" aria-label="Permalink to “commentator()”">​</a></h3><p>Determines the comment author&#39;s information based on the author type and returns an array containing <code>name</code>, <code>email</code>, and <code>url</code>:</p><ul><li><strong>Guest author:</strong> The <code>name</code> and <code>email</code> values are taken from the comment itself, and <code>url</code> is an empty string.</li><li><strong>Customer (<code>Customer</code>):</strong> The name and email address are read from the customer record, and <code>url</code> points to the customer edit page in the admin panel.</li><li><strong>Administrator (<code>User</code>):</strong> The name and email address are read from the administrator record, and <code>url</code> points to the administrator edit page in the admin panel.</li></ul>`,18)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};